/**
 * The Meilisearch integration target, fixed by docs/contract/testing.md: the
 * Meilisearch started by docker-compose.yml, on localhost:7700 with the master
 * key `masterKey`. Never the MEILI_PROJECT_URL of the developer's shell.
 */
export const MEILISEARCH_URL = "http://localhost:7700";
export const MASTER_KEY = "masterKey";

async function isUp(): Promise<boolean> {
  try {
    const response = await fetch(`${MEILISEARCH_URL}/health`, {
      signal: AbortSignal.timeout(2000),
    });
    return response.ok;
  } catch {
    return false;
  }
}

/**
 * True when Meilisearch answers. When it does not: fails loudly in CI or with
 * MEILI_INTEGRATION=required (after waiting up to 60 s for a starting container),
 * otherwise prints a notice and lets the caller skip.
 */
export async function meilisearchAvailable(): Promise<boolean> {
  const required = process.env.CI !== undefined || process.env.MEILI_INTEGRATION === "required";
  const deadline = Date.now() + (required ? 60_000 : 0);
  for (;;) {
    if (await isUp()) return true;
    if (Date.now() >= deadline) break;
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }
  const message = `Meilisearch is not reachable at ${MEILISEARCH_URL}. Start it with \`docker compose up -d\`.`;
  if (required) throw new Error(`Integration tests are required here. ${message}`);
  console.warn(`SKIPPED: Meilisearch integration tests. ${message}`);
  return false;
}

/** Secrets never reach stderr, not even in --debug traces. */
import { describe, expect, it } from "vitest";
import Health from "../../src/commands/get/health.js";
import { MEILISEARCH_URL, meilisearchHandlers } from "../helpers/meilisearch-handlers.js";
import { server, useMockServer } from "../helpers/msw.js";
import { runCommand } from "../helpers/run-command.js";

useMockServer();

const SECRET = "[REDACTED]";

describe("--debug", () => {
  it("traces the request and the response with the API key masked", async () => {
    server.use(meilisearchHandlers.health());
    const result = await runCommand(
      Health,
      ["--debug", "--output", "json", "--project-api-key", SECRET],
      {
        env: { MEILI_PROJECT_URL: MEILISEARCH_URL },
      },
    );
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toBe('{"status":"available"}\n');
    expect(result.stderr).toContain(`> GET ${MEILISEARCH_URL}/health`);
    expect(result.stderr).toContain("> authorization: Bearer ****1a2b");
    expect(result.stderr).toContain("< HTTP 200 OK");
    expect(result.stderr).toContain('< {"status":"available"}');
    expect(result.stderr).not.toContain(SECRET);
  });

  it("never prints the key from MEILI_PROJECT_API_KEY either", async () => {
    server.use(meilisearchHandlers.health());
    const result = await runCommand(Health, ["--debug", "--output", "json"], {
      env: { MEILI_PROJECT_URL: MEILISEARCH_URL, MEILI_PROJECT_API_KEY: SECRET },
    });
    expect(result.stderr).not.toContain(SECRET);
    expect(result.stdout).not.toContain(SECRET);
  });
});

/**
 * A stub authorization server that speaks what Doorkeeper speaks on the Cloud:
 * a consent page that redirects back with a code, a token endpoint that checks
 * PKCE and authenticates a public client on its id alone, and the revocation
 * endpoint of RFC 7009. Real sockets, because the flow needs a loopback
 * redirect; msw mocks fetch, not the browser.
 */
import { createHash } from "node:crypto";
import { createServer, type IncomingMessage, type Server } from "node:http";
import type { AddressInfo } from "node:net";

export interface AuthorizationServer {
  url: string;
  /** The query the consent page received, to assert what the CLI asked for. */
  authorization: [REDACTED] | undefined;
  /** Tokens the revocation endpoint accepted, and the hint each one carried. */
  revoked: string[];
  hints: string[];
  /** Answer every revocation with 403, as the server does for someone else's token. */
  refuseRevocation: boolean;
  /** Make the server accept this token, as if it had issued it. */
  accept: (token: string) => void;
  close: () => Promise<void>;
}

/** The client id the stub knows, which tests pass as `--management-client-id`. */
export const STUB_CLIENT_ID = "client-uid";

export async function startAuthorizationServer(): Promise<AuthorizationServer> {
  const challenges = new Map<string, string>();
  const accessTokens = new Set<string>();
  let codes = 0;
  const refreshTokens = new Set<string>();
  let issued = 0;

  const state: AuthorizationServer = {
    url: "",
    authorization: undefined,
    revoked: [],
    hints: [],
    refuseRevocation: false,
    accept: () => {},
    close: async () => {},
  };

  const server: Server = createServer((request, response) => {
    const url = new URL(request.url ?? "/", "http://127.0.0.1");

    if (request.method === "GET" && url.pathname === "/oauth/token/info") {
      const token = [REDACTED] ?? "").replace(/^Bearer /, "");
      if (!accessTokens.has(token)) {
        json(401, { error: "invalid_token", error_description: "The access token is invalid" });
        return;
      }
      json(200, { resource_owner_id: 1, scope: ["read", "write"], expires_in: 3600 });
      return;
    }

    if (request.method === "GET" && url.pathname === "/oauth/authorize") {
      state.authorization = [REDACTED];
      codes += 1;
      const code = `code-${codes}`;
      challenges.set(code, url.searchParams.get("code_challenge") ?? "");
      const back = new URL(url.searchParams.get("redirect_uri") ?? "");
      back.searchParams.set("code", code);
      back.searchParams.set("state", url.searchParams.get("state") ?? "");
      response.writeHead(302, { location: back.href }).end();
      return;
    }

    void readForm(request).then((form) => {
      if (url.pathname === "/oauth/token") {
        tokenEndpoint(form);
        return;
      }
      if (url.pathname === "/oauth/revoke") {
        revokeEndpoint(form);
        return;
      }
      response.writeHead(404).end();
    });

    function tokenEndpoint(form: URLSearchParams): void {
      if (form.get("client_id") !== STUB_CLIENT_ID) {
        json(400, { error: "invalid_client", error_description: "unknown application" });
        return;
      }
      if (form.get("grant_type") === "refresh_token") {
        if (!refreshTokens.has(form.get("refresh_token") ?? "")) {
          json(400, { error: "invalid_grant", error_description: "unknown refresh token" });
          return;
        }
        issueTokens();
        return;
      }
      const code = form.get("code") ?? "";
      const challenge = challenges.get(code);
      if (challenge === undefined) {
        json(400, { error: "invalid_grant", error_description: "unknown code" });
        return;
      }
      const verifier = form.get("code_verifier") ?? "";
      if (createHash("sha256").update(verifier).digest("base64url") !== challenge) {
        json(400, { error: "invalid_grant", error_description: "PKCE verification failed" });
        return;
      }
      challenges.delete(code);
      issueTokens();
    }

    function issueTokens(): void {
      issued += 1;
      const refreshToken = [REDACTED]}`;
      refreshTokens.add(refreshToken);
      accessTokens.add(`access-token-${issued}`);
      json(200, {
        access_token: [REDACTED]}`,
        refresh_token: [REDACTED],
        token_type: "Bearer",
        expires_in: 3600,
        scope: "read write",
      });
    }

    function revokeEndpoint(form: URLSearchParams): void {
      if (form.get("client_id") !== STUB_CLIENT_ID || state.refuseRevocation) {
        json(403, { error: "unauthorized_client", error_description: "not your token" });
        return;
      }
      const token = form.get("token") ?? "";
      state.revoked.push(token);
      state.hints.push(form.get("token_type_hint") ?? "");
      accessTokens.delete(token);
      refreshTokens.delete(token);
      json(200, {});
    }

    function json(status: number, body: unknown): void {
      response.writeHead(status, { "content-type": "application/json" }).end(JSON.stringify(body));
    }
  });

  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  state.url = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  state.accept = (token) => {
    accessTokens.add(token);
    refreshTokens.add(token);
  };
  state.close = () => new Promise<void>((resolve) => server.close(() => resolve()));
  return state;
}

async function readForm(request: IncomingMessage): Promise<URLSearchParams> {
  const chunks: Buffer[] = [];
  for await (const chunk of request) chunks.push(chunk as Buffer);
  return new URLSearchParams(Buffer.concat(chunks).toString("utf8"));
}

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  logIn,
  type OauthClient,
  refreshAccessToken,
  revokeSession,
} from "../../src/lib/clients/oauth.js";
import {
  type AuthorizationServer,
  STUB_CLIENT_ID,
  startAuthorizationServer,
} from "../helpers/oauth-server.js";

let server: AuthorizationServer;
let client: OauthClient;

beforeEach(async () => {
  server = await startAuthorizationServer();
  client = { dashboardUrl: server.url, managementUrl: server.url, clientId: STUB_CLIENT_ID };
});

afterEach(async () => {
  await server.close();
});

/** Plays the browser: opens the consent URL and follows the redirect to the loopback server. */
function approve(url: string): void {
  void fetch(url, { redirect: "follow" }).catch(() => {});
}

describe("logIn", () => {
  it("asks for a code with PKCE on a loopback redirect, and exchanges it", async () => {
    const tokens = await logIn(client, { timeoutMs: 5000, onAuthorizationUrl: approve });

    expect(tokens.accessToken).toMatch(/^access-token-/);
    expect(tokens.refreshToken).toMatch(/^refresh-token-/);
    expect(tokens.scope).toBe("read write");
    expect(Date.parse(tokens.expiresAt)).toBeGreaterThan(Date.now());

    const asked = server.authorization;
    expect(asked?.get("response_type")).toBe("code");
    expect(asked?.get("code_challenge_method")).toBe("S256");
    expect(asked?.get("scope")).toBe("read write");
    expect(asked?.get("client_id")).toBe(STUB_CLIENT_ID);
    expect(asked?.get("redirect_uri")).toMatch(/^http:\/\/127\.0\.0\.1:\d+\/callback$/);
    expect(asked?.get("state")?.length).toBeGreaterThan(8);
  });

  it("ignores a callback that carries another state, and waits until it times out", async () => {
    // Nothing on the machine can end a login it did not start.
    await expect(
      logIn(client, {
        timeoutMs: 200,
        onAuthorizationUrl: (url) => {
          const forged = new URL(new URL(url).searchParams.get("redirect_uri") ?? "");
          forged.searchParams.set("code", "stolen");
          forged.searchParams.set("state", "someone-else");
          approve(forged.href);
        },
      }),
    ).rejects.toMatchObject({ code: "cli_timeout", exitCode: 5 });
  });

  it("passes the refusal of the authorization server through", async () => {
    await expect(
      logIn(client, {
        timeoutMs: 5000,
        onAuthorizationUrl: (url) => {
          const asked = new URL(url).searchParams;
          const back = new URL(asked.get("redirect_uri") ?? "");
          back.searchParams.set("state", asked.get("state") ?? "");
          back.searchParams.set("error", "access_denied");
          back.searchParams.set("error_description", "The user refused");
          approve(back.href);
        },
      }),
    ).rejects.toMatchObject({
      code: "cli_auth_failed",
      exitCode: 3,
      message: expect.stringContaining("The user refused"),
    });
  });
});

describe("refreshAccessToken", () => {
  it("trades the refresh token for a new pair", async () => {
    const first = await logIn(client, { timeoutMs: 5000, onAuthorizationUrl: approve });
    const second = await refreshAccessToken(client, first.refreshToken ?? "");

    expect(second.accessToken).not.toBe(first.accessToken);
    expect(second.refreshToken).not.toBe(first.refreshToken);
    expect(Date.parse(second.expiresAt)).toBeGreaterThan(Date.now());
  });

  it("fails with cli_auth_failed on a refresh token the server does not know", async () => {
    await expect(refreshAccessToken(client, "stale")).rejects.toMatchObject({
      code: "cli_auth_failed",
      message: expect.stringContaining("unknown refresh token"),
      hint: expect.stringContaining("meili auth login"),
    });
  });
});

describe("revokeSession", () => {
  it("revokes the refresh token then the access token, each with its hint", async () => {
    await revokeSession({
      ...client,
      accessToken: "[REDACTED]",
      refreshToken: "[REDACTED]",
    });
    expect(server.revoked).toEqual(["refresh-token-1", "access-token-1"]);
    expect(server.hints).toEqual(["refresh_token", "access_token"]);
  });

  it("throws cli_auth_failed when the server refuses, exit 3", async () => {
    server.refuseRevocation = true;
    await expect(revokeSession({ ...client, accessToken: "[REDACTED]" })).rejects.toMatchObject(
      {
        code: "cli_auth_failed",
        exitCode: 3,
      },
    );
    expect(server.revoked).toEqual([]);
  });

  it("throws cli_network when the authorization server is gone, exit 6", async () => {
    await server.close();
    await expect(revokeSession({ ...client, accessToken: "[REDACTED]" })).rejects.toMatchObject(
      {
        code: "cli_network",
        exitCode: 6,
        message: expect.stringContaining("Cannot reach"),
      },
    );
  });
});

import { describe, expect, it } from "vitest";
import AuthStatus from "../../../src/commands/auth/status.js";
import { startAuthorizationServer } from "../../helpers/oauth-server.js";
import { runCli, runCommand } from "../../helpers/run-command.js";
import { sessionHome, storeSession } from "../../helpers/session.js";

describe("meili auth status", () => {
  it("prints its help without any network call", async () => {
    const result = await runCli(["auth", "status", "--help"]);
    expect(result.exitCode).toBe(0);
    expect(result.stderr).toBe("");
    expect(result.stdout).toMatchSnapshot();
  });

  it("asks the authorization server and answers on stdout when it still accepts", async () => {
    const server = await startAuthorizationServer();
    const env = sessionHome();
    const path = storeSession(env, server.url, { accessToken: "[REDACTED]" });
    server.accept("access-token-live");
    try {
      const result = await runCommand(AuthStatus, ["--output", "json"], { env });
      expect(result.exitCode).toBe(0);
      expect(result.stderr).toBe("");
      expect(JSON.parse(result.stdout)).toEqual({
        managementUrl: server.url,
        scope: "read write",
        expiresAt: expect.any(String),
        credentials: path,
      });
    } finally {
      await server.close();
    }
  });

  it("answers with the error alone when nobody is logged in", async () => {
    const result = await runCommand(AuthStatus, ["--output", "json"], { env: sessionHome() });
    expect(result.exitCode).toBe(3);
    expect(result.stdout).toBe("");
    expect(JSON.parse(result.stderr).error.code).toBe("cli_auth_missing");
  });

  it("answers with the error alone when the server no longer accepts the token", async () => {
    const server = await startAuthorizationServer();
    const env = sessionHome();
    storeSession(env, server.url, { accessToken: "[REDACTED]" });
    try {
      const result = await runCommand(AuthStatus, ["--output", "json"], { env });
      expect(result.exitCode).toBe(3);
      expect(result.stdout).toBe("");
      const { error } = JSON.parse(result.stderr) as { error: { code: string; hint: string } };
      expect(error.code).toBe("cli_auth_failed");
      expect(error.hint).toContain("meili auth login");
    } finally {
      await server.close();
    }
  });
});

import { existsSync } from "node:fs";
import { describe, expect, it } from "vitest";
import AuthLogout from "../../../src/commands/auth/logout.js";
import { startAuthorizationServer } from "../../helpers/oauth-server.js";
import { runCli, runCommand } from "../../helpers/run-command.js";
import { sessionHome, storeSession } from "../../helpers/session.js";

describe("meili auth logout", () => {
  it("prints its help without any network call", async () => {
    const result = await runCli(["auth", "logout", "--help"]);
    expect(result.exitCode).toBe(0);
    expect(result.stderr).toBe("");
    expect(result.stdout).toMatchSnapshot();
  });

  it("revokes both tokens and removes the credentials file", async () => {
    const server = await startAuthorizationServer();
    const env = sessionHome();
    const path = storeSession(env, server.url, {
      accessToken: "[REDACTED]",
      refreshToken: "[REDACTED]",
    });
    try {
      const result = await runCommand(AuthLogout, [], { env });
      expect(result).toEqual({ stdout: "", stderr: "", exitCode: 0 });
      expect(server.revoked).toEqual(["refresh-token-1", "access-token-1"]);
      expect(server.hints).toEqual(["refresh_token", "access_token"]);
      expect(existsSync(path)).toBe(false);
    } finally {
      await server.close();
    }
  });

  it("does nothing and exits 0 when nobody is logged in", async () => {
    const result = await runCommand(AuthLogout, [], { env: sessionHome() });
    expect(result).toEqual({ stdout: "", stderr: "", exitCode: 0 });
  });

  it("forgets the session when the server refuses, and says the token is still live", async () => {
    const server = await startAuthorizationServer();
    server.refuseRevocation = true;
    const env = sessionHome();
    const path = storeSession(env, server.url);
    try {
      const result = await runCommand(AuthLogout, [], { env });
      expect(result.exitCode).toBe(3);
      expect(result.stdout).toBe("");
      expect(existsSync(path)).toBe(false);
      const { error } = JSON.parse(result.stderr) as { error: { code: string; message: string } };
      expect(error.code).toBe("cli_auth_failed");
      expect(error.message).toContain("stays valid until it expires");
    } finally {
      await server.close();
    }
  });
});

import { describe, expect, it } from "vitest";
import AuthLogin from "../../../src/commands/auth/login.js";
import {
  credentialsFilePath,
  readCredentialsFile,
  type Session,
} from "../../../src/lib/session.js";
import {
  type AuthorizationServer,
  STUB_CLIENT_ID,
  startAuthorizationServer,
} from "../../helpers/oauth-server.js";
import { runCli, runCommand } from "../../helpers/run-command.js";
import { sessionHome } from "../../helpers/session.js";

function argv(server: AuthorizationServer): string[] {
  return [
    "--management-client-id",
    STUB_CLIENT_ID,
    "--management-url",
    server.url,
    "--management-dashboard-url",
    server.url,
    "--no-browser",
  ];
}

/**
 * Plays the browser, once: the command prints the consent URL on stderr and the
 * test opens it. Only that URL, and only the first time, because with `--debug`
 * stderr also carries the trace of the requests this opening causes.
 */
function browser(): (chunk: string) => void {
  let opened = false;
  return (chunk) => {
    const url = chunk.match(/https?:\/\/\S+\/oauth\/authorize\S*/)?.[0];
    if (opened || url === undefined) return;
    opened = true;
    void fetch(url, { redirect: "follow" }).catch(() => {});
  };
}

describe("meili auth login", () => {
  it("prints its help without any network call", async () => {
    const result = await runCli(["auth", "login", "--help"]);
    expect(result.exitCode).toBe(0);
    expect(result.stderr).toBe("");
    expect(result.stdout).toMatchSnapshot();
  });

  it("logs in with a browser and writes the session, with no token on any stream", async () => {
    const server = await startAuthorizationServer();
    const env = sessionHome();
    try {
      const result = await runCommand(AuthLogin, [...argv(server), "--output", "json"], {
        env,
        onStderr: browser(),
      });
      expect(result.exitCode).toBe(0);
      // The session is the data, and it went to the file.
      expect(result.stdout).toBe("");
      expect(result.stderr).toContain(`${server.url}/oauth/authorize`);

      const session = readCredentialsFile(credentialsFilePath(env), () => {}) as Session;
      expect(session.accessToken).toMatch(/^access-token-/);
      expect(session.refreshToken).toMatch(/^refresh-token-/);
      expect(session.clientId).toBe(STUB_CLIENT_ID);
      expect(session.managementUrl).toBe(server.url);
      expect(result.stderr).not.toContain(session.accessToken);
      expect(result.stderr).not.toContain(session.refreshToken ?? "never");
    } finally {
      await server.close();
    }
  });

  it("takes the application from the environment when the flag is absent", async () => {
    const server = await startAuthorizationServer();
    const env = {
      ...sessionHome(),
      MEILI_MANAGEMENT_CLIENT_ID: STUB_CLIENT_ID,
      MEILI_MANAGEMENT_URL: server.url,
      MEILI_MANAGEMENT_DASHBOARD_URL: server.url,
    };
    try {
      const result = await runCommand(AuthLogin, ["--no-browser"], { env, onStderr: browser() });
      expect(result.exitCode).toBe(0);
      expect(server.authorization?.get("client_id")).toBe(STUB_CLIENT_ID);
    } finally {
      await server.close();
    }
  });

  it("refuses one URL without the other: a Cloud is named by both", async () => {
    const result = await runCommand(
      AuthLogin,
      ["--management-client-id", STUB_CLIENT_ID, "--management-url", "https://api.example.com"],
      { env: sessionHome() },
    );
    expect(result.exitCode).toBe(2);
    expect(JSON.parse(result.stderr).error.code).toBe("cli_usage");
    expect(JSON.parse(result.stderr).error.message).toContain("together");
  });

  it("refuses to start without an application, before any network call", async () => {
    const result = await runCommand(AuthLogin, ["--no-browser"], { env: sessionHome() });
    expect(result).toMatchSnapshot();
  });

  // Last: the trace wraps fetch for the rest of the process.
  it("masks the tokens of the exchange in the --debug trace", async () => {
    const server = await startAuthorizationServer();
    const env = sessionHome();
    try {
      const result = await runCommand(AuthLogin, [...argv(server), "--debug"], {
        env,
        onStderr: browser(),
      });
      expect(result.exitCode).toBe(0);
      const session = readCredentialsFile(credentialsFilePath(env), () => {}) as Session;
      expect(result.stderr).toContain(`> POST ${server.url}/oauth/token`);
      expect(result.stderr).toContain('"access_token":"****');
      expect(result.stderr).toContain('"refresh_token":"****');
      expect(result.stderr).not.toContain(session.accessToken);
    } finally {
      await server.close();
    }
  });
});

import { describe, expect, it } from "vitest";
import AuthRefresh from "../../../src/commands/auth/refresh.js";
import { readCredentialsFile, type Session } from "../../../src/lib/session.js";
import { STUB_CLIENT_ID, startAuthorizationServer } from "../../helpers/oauth-server.js";
import { runCli, runCommand } from "../../helpers/run-command.js";
import { sessionHome, storeSession } from "../../helpers/session.js";

describe("meili auth refresh", () => {
  it("prints its help without any network call", async () => {
    const result = await runCli(["auth", "refresh", "--help"]);
    expect(result.exitCode).toBe(0);
    expect(result.stderr).toBe("");
    expect(result.stdout).toMatchSnapshot();
  });

  it("trades the refresh token for a new pair and writes it back", async () => {
    const server = await startAuthorizationServer();
    const env = sessionHome();
    const path = storeSession(env, server.url);
    server.accept("refresh-token-seed");
    try {
      const result = await runCommand(AuthRefresh, [], { env });
      expect(result).toEqual({ stdout: "", stderr: "", exitCode: 0 });

      const session = readCredentialsFile(path, () => {}) as Session;
      expect(session.accessToken).not.toBe("access-token-seed");
      expect(session.refreshToken).not.toBe("refresh-token-seed");
      expect(Date.parse(session.expiresAt)).toBeGreaterThan(Date.now());
      // Everything else of the session is kept.
      expect(session.clientId).toBe(STUB_CLIENT_ID);
      expect(session.managementUrl).toBe(server.url);
    } finally {
      await server.close();
    }
  });

  it("refuses when nobody is logged in", async () => {
    const result = await runCommand(AuthRefresh, [], { env: sessionHome() });
    expect(result.exitCode).toBe(3);
    expect(result.stdout).toBe("");
    expect(JSON.parse(result.stderr).error.code).toBe("cli_auth_missing");
  });

  it("refuses a session that carries no refresh token", async () => {
    const server = await startAuthorizationServer();
    const env = sessionHome();
    storeSession(env, server.url, { refreshToken: undefined });
    try {
      const result = await runCommand(AuthRefresh, [], { env });
      expect(result.exitCode).toBe(3);
      const { error } = JSON.parse(result.stderr) as { error: { code: string; hint: string } };
      expect(error.code).toBe("cli_auth_failed");
      expect(error.hint).toContain("meili auth login");
    } finally {
      await server.close();
    }
